            let a2 = { let x = &x[at..]; x[0] as i64 };
            at += 1;
            if x.len() < at + 1 { return None; }
            let a3 = { let x = &x[at..]; x[0] };
            at += 1;
            if x.len() < at + 1 { return None; }
            let a4 = { let x = &x[at..]; x[0] };
            at += 1;
            if x.len() != at { return None; }
            let r = crate::kpistats::kpi_time_to(&mut io0, &mut io1, a2, a3, a4);
