            let n7 = x[at] as usize;
            if x.len() < at + 1 + n7 { return None; }
            let mut io7 = x[at + 1..at + 1 + n7].to_vec();
            at += 1 + n7;
            if x.len() != at { return None; }
            let r = crate::kpistats::kpi_time_to_from(&mut io0, &mut io1, a2, a3, a4, a5, &mut io6, &mut io7);
